&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
    &lt;title&gt;校园经历&lt;/title&gt;
    &lt;style&gt;
        body {
            font-family: Arial, sans-serif;
        }
        .container {
            width: 80%;
            margin: auto;
        }
        .image-upload {
            padding: 20px;
            border: 1px solid #ddd;
            margin-bottom: 20px;
        }
        .image-upload input[type=file] {
            display: block;
            width: 100%;
            height: 40px;
            padding: 5px;
        }
        .image-list img {
            width: 200px;
            height: auto;
            margin-bottom: 10px;
        }
    </style>
&lt;/head&gt;
&lt;body&gt;
    &lt;div class="container"&gt;
        &lt;h1&gt;校园经历&lt;/h1&gt;
        &lt;div class="image-upload"&gt;
            &lt;form action="/upload" method="post" enctype="multipart/form-data"&gt;
                &lt;input type="file" name="file"&gt;
                &lt;input type="submit" value="上传图片"&gt;
            </form>
        &lt;/div&gt;
        &lt;div class="image-list"&gt;
            <!-- 此处将动态生成图片列表 -->
        &lt;/div&gt;
    &lt;/div&gt;
&lt;/body&gt;
&lt;/html&gt;
